import time, asyncio, requests

@app.get("/a")
async def a():
    requests.get(PARTNER, timeout=5)     # blocking call, ~2 s p99
    return {"ok": True}

@app.get("/b")
def b():
    time.sleep(2)                        # blocking, but plain def
    return {"ok": True}

@app.get("/c")
async def c():
    await asyncio.sleep(2)               # async sleep
    return {"ok": True}

