# Три хендлера: блокировка в async def, блокировка в def, await в async def
import time, asyncio, requests

@app.get("/a")
async def a():
    requests.get(PARTNER, timeout=5)     # блокирующий вызов, p99 ~2 с
    return {"ok": True}

@app.get("/b")
def b():
    time.sleep(2)                        # блокирует, но обычный def
    return {"ok": True}

@app.get("/c")
async def c():
    await asyncio.sleep(2)               # асинхронный сон
    return {"ok": True}

