from fastapi import FastAPI

app = FastAPI()

@app.on_event("startup")
async def warm():
    app.state.config = requests.get("http://config/svc", timeout=10).json()

@app.get("/quote/{sym}")
async def quote(sym: str):
    # upstream pricing API, sync client
    r = requests.get(f"http://prices/{sym}", timeout=2)
    return r.json()

